    public static void start(FlawlessVisualPacket packet) {
        Minecraft minecraft = Minecraft.getInstance();

        if (minecraft.level == null) {
            return;
        }

        ANIMATIONS.removeIf(
                animation ->
                        animation.entityId == packet.entityId() &&
                                (
                                        animation.type == packet.type() ||
                                        packet.type() == FlawlessVisualPacket.Type.ARROW_IMPACT &&
                                                animation.type == FlawlessVisualPacket.Type.ARROW_TRAIL ||
                                        packet.type() == FlawlessVisualPacket.Type.ULTIMATE_CLOSE &&
                                                animation.type == FlawlessVisualPacket.Type.ULTIMATE
                                )
        );

        ANIMATIONS.add(
                new Animation(
                        packet.type(),
                        packet.entityId(),
                        new Vec3(packet.x(), packet.y(), packet.z()),
                        minecraft.level.getGameTime(),
                        Math.max(1, packet.duration()),
                        packet.variant()
                )
        );
    }

    @SubscribeEvent
    public static void onRenderLevel(RenderLevelStageEvent event) {
        if (event.getStage() != RenderLevelStageEvent.Stage.AFTER_PARTICLES) {
            return;
        }

        Minecraft minecraft = Minecraft.getInstance();

        if (minecraft.level == null || minecraft.player == null) {
            ANIMATIONS.clear();
            return;
        }

        float partialTick = event.getPartialTick();
        double now = minecraft.level.getGameTime() + partialTick;
        PoseStack poseStack = event.getPoseStack();
        Vec3 camera = event.getCamera().getPosition();
        MultiBufferSource.BufferSource buffers =
                minecraft.renderBuffers().bufferSource();
        RenderType renderType = RenderType.lines();
        VertexConsumer consumer = buffers.getBuffer(renderType);

        poseStack.pushPose();
        poseStack.translate(-camera.x, -camera.y, -camera.z);

        drawHeldAnimation(
                minecraft.player,
                now,
                partialTick,
                poseStack,
                consumer
        );
        spawnHeldParticles(
                minecraft,
                minecraft.player,
                minecraft.level.getGameTime()
        );

        Iterator<Animation> iterator = ANIMATIONS.iterator();

        while (iterator.hasNext()) {
            Animation animation = iterator.next();
            double age = now - animation.startTick;

            if (age >= animation.duration) {
                iterator.remove();
                continue;
            }

            Entity entity = minecraft.level.getEntity(
                    animation.entityId
            );

            if (
                    animation.type == FlawlessVisualPacket.Type.ARROW_TRAIL &&
                    entity == null
            ) {
                if (age > 5.0D) {
                    iterator.remove();
                }
                continue;
            }

            Vec3 center =
                    resolveAnimationCenter(
                            animation,
                            entity,
                            partialTick
                    );

            if (animation.type == FlawlessVisualPacket.Type.ARROW_TRAIL) {
                recordTrailPoint(
                        animation,
                        center,
                        minecraft.level.getGameTime()
                );
            }

            float alpha = animationAlpha(age, animation.duration);

            drawAnimation(
                    animation,
                    center,
                    age,
                    alpha,
                    poseStack,
                    consumer
            );
            spawnAnimationParticles(
                    minecraft,
                    animation,
                    center,
                    minecraft.level.getGameTime(),
                    age
            );
        }

        buffers.endBatch(renderType);
        drawSpecialEffectSurfaces(
                minecraft,
                now,
                partialTick,
                poseStack,
                buffers
        );
        poseStack.popPose();
        buffers.endBatch();
    }

    private static void drawHeldAnimation(
            Player player,
            double time,
            float partialTick,
            PoseStack poseStack,
            VertexConsumer consumer
    ) {
        if (!player.getMainHandItem().is(
                ModItems.FLAWLESS_BENEDICTION_LEGACY.get()
        )) {
            return;
        }

        Vec3 center = player.getPosition(partialTick);
        double phase = time * 0.10D;
        double pulse = 1.0D + Math.sin(time * 0.18D) * 0.06D;

        ringXZ(
                poseStack,
                consumer,
                center.add(0.0D, 0.06D, 0.0D),
                0.92D * pulse,
                40,
                phase,
                PETAL_PINK,
                ICE_BLUE,
                0.52F
        );

        if (player.isUsingItem()) {
            magicCircleXZ(
                    poseStack,
                    consumer,
                    center.add(0.0D, 0.08D, 0.0D),
                    1.48D * pulse,
                    phase,
                    DEEP_PINK,
                    ICE_BLUE,
                    0.52F
            );
            flowerXZ(
                    poseStack,
                    consumer,
                    center.add(0.0D, 0.10D, 0.0D),
                    1.22D * pulse,
                    60,
                    -phase * 1.35D,
                    DEEP_PINK,
                    ICE_BLUE,
                    0.66F
            );
            ringXZ(
                    poseStack,
                    consumer,
                    center.add(0.0D, 0.14D, 0.0D),
                    1.48D * pulse,
                    52,
                    phase * 1.8D,
                    ICE_BLUE,
                    PETAL_PINK,
                    0.52F
            );
        }
    }

    private static void drawAnimation(
            Animation animation,
            Vec3 center,
            double age,
            float alpha,
            PoseStack poseStack,
            VertexConsumer consumer
    ) {
        double phase = age * 0.10D;
        double growth = Math.min(1.0D, (age + 1.0D) / 10.0D);

        switch (animation.type) {
            case MODE_WEATHER -> drawWeatherMode(
                    poseStack,
                    consumer,
                    center,
                    phase,
                    growth,
                    alpha
            );
            case MODE_SUN_MOON -> drawSunMoonMode(
                    poseStack,
                    consumer,
                    center,
                    phase,
                    growth,
                    alpha
            );
            case MODE_FLAWLESS -> drawFlawlessMode(
                    poseStack,
                    consumer,
                    center,
                    phase,
                    growth,
                    alpha
            );
            case WEATHER_SKILL -> drawWeather(
                    poseStack,
                    consumer,
                    center,
                    phase,
                    growth,
                    alpha
            );
            case SUN_MOON_SKILL -> drawSunMoon(
                    poseStack,
                    consumer,
                    center,
                    phase,
                    growth,
                    alpha
            );
            case BLOOM_STACK -> drawBloomStack(
                    poseStack,
                    consumer,
                    center,
                    animation.variant,
                    phase,
                    growth,
                    alpha
            );
            case FLAWLESS_BLOOM -> drawFlawlessBloom(
                    poseStack,
                    consumer,
                    center,
                    animation.variant,
                    phase,
                    growth,
                    alpha
            );
            case ULTIMATE -> {
                compactUltimateLines = true;
                drawUltimate(
                        poseStack,
                        consumer,
                        center,
                        phase,
                        growth,
                        alpha
                );
                compactUltimateLines = false;
            }
            case ULTIMATE_CLOSE -> {
                compactUltimateLines = true;
                drawUltimateClose(
                        poseStack,
                        consumer,
                        center,
                        age,
                        phase,
                        alpha
                );
                compactUltimateLines = false;
            }
            case ARROW_TRAIL -> drawArrowTrail(
                    poseStack,
                    consumer,
                    animation,
                    center,
                    phase,
                    alpha
            );
            case ARROW_IMPACT -> drawArrowImpact(
                    poseStack,
                    consumer,
                    center,
                    animation.variant,
                    age,
                    phase,
                    alpha
            );
        }
    }

