    private static void weatherCurtain(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double radius,
            double height,
            double phase,
            float alpha
    ) {
        for (int i = 0; i < 14; i++) {
            double angle = phase * 1.6D + Math.PI * 2.0D * i / 14.0D;
            double startHeight = height * (0.48D + (i % 4) * 0.14D);
            Vec3 start = center.add(
                    Math.cos(angle) * radius,
                    startHeight,
                    Math.sin(angle) * radius
            );
            Vec3 end = start.add(
                    -Math.sin(angle) * 0.18D,
                    -0.72D,
                    Math.cos(angle) * 0.18D
            );

            line(
                    poseStack,
                    consumer,
                    start,
                    end,
                    i % 3 == 0 ? PETAL_PINK : ICE_BLUE,
                    alpha
            );
        }
    }

    private static void sunMoonOrbs(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double radius,
            double phase,
            double growth,
            float alpha
    ) {
        Vec3 sun = center.add(
                Math.cos(phase) * radius,
                Math.sin(phase * 0.5D) * 0.36D,
                Math.sin(phase) * radius
        );
        Vec3 moon = center.add(
                -Math.cos(phase) * radius,
                -Math.sin(phase * 0.5D) * 0.36D,
                -Math.sin(phase) * radius
        );

        orbitingCrown(
                poseStack,
                consumer,
                sun,
                0.42D * growth,
                phase * 2.0D,
                SUN_GOLD,
                CRYSTAL_WHITE,
                alpha * 0.92F
        );
        orbitingCrown(
                poseStack,
                consumer,
                moon,
                0.42D * growth,
                -phase * 2.0D,
                MOON_BLUE,
                ICE_BLUE,
                alpha * 0.92F
        );
        line(
                poseStack,
                consumer,
                sun,
                moon,
                ELYSIA_VIOLET,
                alpha * 0.62F
        );
    }

