    private static void drawUltimateClose(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double age,
            double phase,
            float alpha
    ) {
        if (age < 40.0D) {
            double morph =
                    Math.min(
                            1.0D,
                            age / 40.0D
                    );

            double pulse =
                    1.0D +
                            Math.sin(age * 0.42D) * 0.05D;

            Vec3 haloCenter =
                    center.add(
                            0.0D,
                            5.2D,
                            0.0D
                    );

            verticalRingCross(
                    poseStack,
                    consumer,
                    haloCenter,
                    (4.8D + morph * 1.4D) * pulse,
                    144,
                    -phase * 1.3D,
                    DEEP_PINK,
                    ICE_BLUE,
                    alpha * 0.92F
            );

            flowerVerticalCross(
                    poseStack,
                    consumer,
                    haloCenter,
                    (4.15D + morph * 1.1D) * pulse,
                    144,
                    phase * 1.8D,
                    PETAL_PINK,
                    ELYSIA_VIOLET,
                    alpha * 0.82F
            );

            ringXZ(
                    poseStack,
                    consumer,
                    center.add(
                            0.0D,
                            0.08D,
                            0.0D
                    ),
                    2.2D + morph * 1.3D,
                    72,
                    phase,
                    DEEP_PINK,
                    ICE_BLUE,
                    alpha * 0.42F
            );

            orbitingCrown(
                    poseStack,
                    consumer,
                    center.add(
                            0.0D,
                            2.0D + morph * 7.0D,
                            0.0D
                    ),
                    1.15D + morph * 2.15D,
                    phase * 1.8D,
                    DEEP_PINK,
                    CRYSTAL_WHITE,
                    alpha * (float) morph
            );

            return;
        }

        double reveal =
                Math.min(
                        1.0D,
                        (age - 40.0D) / 8.0D
                );

        double pulse =
                1.0D +
                        Math.sin(age * 0.28D) * 0.025D;

        magicCircleXZ(
                poseStack,
                consumer,
                center.add(0.0D, 0.10D, 0.0D),
                7.25D * pulse * reveal,
                -phase * 1.15D,
                DEEP_PINK,
                ICE_BLUE,
                alpha * 0.90F
        );

        flowerXZ(
                poseStack,
                consumer,
                center.add(0.0D, 0.14D, 0.0D),
                6.75D * pulse * reveal,
                144,
                phase * 1.6D,
                PETAL_PINK,
                ELYSIA_VIOLET,
                alpha * 0.82F
        );

        verticalRingCross(
                poseStack,
                consumer,
                center.add(
                        0.0D,
                        11.0D * reveal,
                        0.0D
                ),
                8.6D * reveal,
                176,
                phase * 0.32D,
                PETAL_PINK,
                ICE_BLUE,
                alpha * 0.58F
        );
    }

