    private static void drawGoddessPlane(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            Vec3 axis,
            double phase,
            double reveal,
            float alpha
    ) {
        Vec3 haloCenter =
                center.add(
                        0.0D,
                        10.5D * reveal,
                        0.0D
                );

        ringVerticalPlane(
                poseStack,
                consumer,
                haloCenter,
                axis,
                6.65D * reveal,
                160,
                phase * 0.12D,
                PETAL_PINK,
                ICE_BLUE,
                alpha * 0.72F
        );

        ringVerticalPlane(
                poseStack,
                consumer,
                haloCenter,
                axis,
                5.55D * reveal,
                144,
                -phase * 0.18D,
                ELYSIA_VIOLET,
                CRYSTAL_WHITE,
                alpha * 0.62F
        );

        for (int i = 0; i < 28; i++) {
            double angle =
                    phase * 0.08D +
                            Math.PI * 2.0D * i / 28.0D;

            double innerRadius =
                    6.75D * reveal;

            double outerRadius =
                    (
                            i % 2 == 0
                                    ? 8.15D
                                    : 7.55D
                    ) * reveal;

            Vec3 inner =
                    planePoint(
                            haloCenter,
                            axis,
                            Math.cos(angle) * innerRadius,
                            Math.sin(angle) * innerRadius
                    );

            Vec3 outer =
                    planePoint(
                            haloCenter,
                            axis,
                            Math.cos(angle) * outerRadius,
                            Math.sin(angle) * outerRadius
                    );

            line(
                    poseStack,
                    consumer,
                    inner,
                    outer,
                    i % 3 == 0
                            ? CRYSTAL_WHITE
                            : i % 2 == 0
                            ? PETAL_PINK
                            : ICE_BLUE,
                    alpha * 0.64F
            );
        }

        Vec3 headCenter =
                center.add(
                        0.0D,
                        10.25D * reveal,
                        0.0D
                );

        ringVerticalPlane(
                poseStack,
                consumer,
                headCenter,
                axis,
                1.12D * reveal,
                72,
                phase * 0.25D,
                CRYSTAL_WHITE,
                PETAL_PINK,
                alpha * 0.92F
        );

        for (int i = 0; i < 18; i++) {
            double angle =
                    Math.PI * 2.0D * i / 18.0D;

            Vec3 inner =
                    planePoint(
                            headCenter,
                            axis,
                            Math.cos(angle) * 1.42D * reveal,
                            Math.sin(angle) * 1.42D * reveal
                    );

            Vec3 outer =
                    planePoint(
                            headCenter,
                            axis,
                            Math.cos(angle) *
                                    (
                                            i % 2 == 0
                                                    ? 2.75D
                                                    : 2.20D
                                    ) * reveal,
                            Math.sin(angle) *
                                    (
                                            i % 2 == 0
                                                    ? 2.75D
                                                    : 2.20D
                                    ) * reveal
                    );

            line(
                    poseStack,
                    consumer,
                    inner,
                    outer,
                    i % 2 == 0
                            ? CRYSTAL_WHITE
                            : PETAL_PINK,
                    alpha * 0.72F
            );
        }

        Vec3 leftShoulder =
                planePoint(
                        center,
                        axis,
                        -2.05D * reveal,
                        8.65D * reveal
                );

        Vec3 rightShoulder =
                planePoint(
                        center,
                        axis,
                        2.05D * reveal,
                        8.65D * reveal
                );

        Vec3 leftWaist =
                planePoint(
                        center,
                        axis,
                        -1.05D * reveal,
                        6.15D * reveal
                );

        Vec3 rightWaist =
                planePoint(
                        center,
                        axis,
                        1.05D * reveal,
                        6.15D * reveal
                );

        Vec3 leftHem =
                planePoint(
                        center,
                        axis,
                        -6.85D * reveal,
                        0.35D
                );

        Vec3 rightHem =
                planePoint(
                        center,
                        axis,
                        6.85D * reveal,
                        0.35D
                );

        line(
                poseStack,
                consumer,
                leftShoulder,
                leftWaist,
                PETAL_PINK,
                alpha * 0.92F
        );

        line(
                poseStack,
                consumer,
                rightShoulder,
                rightWaist,
                ICE_BLUE,
                alpha * 0.92F
        );

        line(
                poseStack,
                consumer,
                leftWaist,
                leftHem,
                PETAL_PINK,
                alpha * 0.94F
        );

        line(
                poseStack,
                consumer,
                rightWaist,
                rightHem,
                ICE_BLUE,
                alpha * 0.94F
        );

        line(
                poseStack,
                consumer,
                leftHem,
                rightHem,
                ELYSIA_VIOLET,
                alpha * 0.82F
        );

        for (int i = 0; i <= 12; i++) {
            double ratio =
                    i / 12.0D;

            double waistHorizontal =
                    -1.05D + 2.10D * ratio;

            double hemHorizontal =
                    -6.65D + 13.30D * ratio;

            Vec3 waist =
                    planePoint(
                            center,
                            axis,
                            waistHorizontal * reveal,
                            6.10D * reveal
                    );

            Vec3 hem =
                    planePoint(
                            center,
                            axis,
                            hemHorizontal * reveal,
                            0.42D
                    );

            line(
                    poseStack,
                    consumer,
                    waist,
                    hem,
                    i % 2 == 0
                            ? PETAL_PINK
                            : ICE_BLUE,
                    alpha * 0.46F
            );
        }

        Vec3 chest =
                planePoint(
                        center,
                        axis,
                        0.0D,
                        7.55D * reveal
                );

        Vec3 leftHand =
                planePoint(
                        center,
                        axis,
                        0.45D * reveal,
                        8.05D * reveal
                );

        Vec3 rightHand =
                planePoint(
                        center,
                        axis,
                        -0.35D * reveal,
                        9.25D * reveal
                );

        line(
                poseStack,
                consumer,
                leftShoulder,
                chest,
                PETAL_PINK,
                alpha * 0.88F
        );

        line(
                poseStack,
                consumer,
                chest,
                leftHand,
                CRYSTAL_WHITE,
                alpha * 0.88F
        );

        line(
                poseStack,
                consumer,
                rightShoulder,
                chest,
                ICE_BLUE,
                alpha * 0.88F
        );

        line(
                poseStack,
                consumer,
                chest,
                rightHand,
                CRYSTAL_WHITE,
                alpha * 0.88F
        );

        line(
                poseStack,
                consumer,
                rightHand,
                planePoint(
                        center,
                        axis,
                        -0.05D * reveal,
                        10.0D * reveal
                ),
                PETAL_PINK,
                alpha * 0.82F
        );

        Vec3 leftHair =
                planePoint(
                        center,
                        axis,
                        -0.82D * reveal,
                        9.55D * reveal
                );

        Vec3 rightHair =
                planePoint(
                        center,
                        axis,
                        0.82D * reveal,
                        9.55D * reveal
                );

        line(
                poseStack,
                consumer,
                leftHair,
                planePoint(
                        center,
                        axis,
                        -3.65D * reveal,
                        5.35D * reveal
                ),
                PETAL_PINK,
                alpha * 0.76F
        );

        line(
                poseStack,
                consumer,
                rightHair,
                planePoint(
                        center,
                        axis,
                        3.65D * reveal,
                        5.35D * reveal
                ),
                ICE_BLUE,
                alpha * 0.76F
        );

        line(
                poseStack,
                consumer,
                leftShoulder,
                planePoint(
                        center,
                        axis,
                        -6.15D * reveal,
                        3.75D * reveal
                ),
                ELYSIA_VIOLET,
                alpha * 0.68F
        );

        line(
                poseStack,
                consumer,
                rightShoulder,
                planePoint(
                        center,
                        axis,
                        6.15D * reveal,
                        3.75D * reveal
                ),
                PETAL_PINK,
                alpha * 0.68F
        );
    }

    private static void ringVerticalPlane(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            Vec3 axis,
            double radius,
            int segments,
            double phase,
            Color first,
            Color second,
            float alpha
    ) {
        Vec3 previous = null;

        for (int i = 0; i <= segments; i++) {
            double angle =
                    phase +
                            Math.PI * 2.0D * i / segments;

            Vec3 current =
                    planePoint(
                            center,
                            axis,
                            Math.cos(angle) * radius,
                            Math.sin(angle) * radius
                    );

            if (previous != null) {
                line(
                        poseStack,
                        consumer,
                        previous,
                        current,
                        mix(
                                first,
                                second,
                                i / (float) segments
                        ),
                        alpha
                );
            }

            previous = current;
        }
    }

    private static Vec3 planePoint(
            Vec3 center,
            Vec3 axis,
            double horizontal,
            double vertical
    ) {
        return center.add(
                axis.x * horizontal,
                vertical,
                axis.z * horizontal
        );
    }

    private static void drawSignetFrames(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double radius,
            double rotation,
            double growth,
            float alpha
    ) {
        for (int i = 0; i < DOMAIN_SIGNETS.size(); i++) {
            double angle = rotation
                    + Math.PI * 2.0D * i / DOMAIN_SIGNETS.size();
            Vec3 signetCenter = center.add(
                    Math.cos(angle) * radius,
                    0.20D,
                    Math.sin(angle) * radius
            );

            ringXZ(
                    poseStack,
                    consumer,
                    signetCenter,
                    0.68D * growth,
                    34,
                    -rotation * 2.0D + i * 0.2D,
                    i % 2 == 0 ? PETAL_PINK : ICE_BLUE,
                    CRYSTAL_WHITE,
                    alpha * 0.88F
            );
            diamondCross(
                    poseStack,
                    consumer,
                    signetCenter.add(0.0D, 0.20D, 0.0D),
                    0.16D * growth,
                    rotation * 3.2D + i,
                    i % 3 == 0 ? CRYSTAL_WHITE : PETAL_PINK,
                    alpha * 0.92F
            );
            line(
                    poseStack,
                    consumer,
                    center.add(
                            Math.cos(angle) * radius * 0.82D,
                            0.18D,
                            Math.sin(angle) * radius * 0.82D
                    ),
                    signetCenter,
                    i % 2 == 0 ? DEEP_PINK : ICE_BLUE,
                    alpha * 0.42F
            );
        }
    }

