    private static void drawSpecialEffectSurfaces(
            Minecraft minecraft,
            double now,
            float partialTick,
            PoseStack poseStack,
            MultiBufferSource.BufferSource buffers
    ) {
        if (minecraft.level == null) {
            return;
        }

        for (Animation animation : ANIMATIONS) {
            double age = now - animation.startTick;
            Entity entity = minecraft.level.getEntity(animation.entityId);
            Vec3 center =
                    resolveAnimationCenter(
                            animation,
                            entity,
                            partialTick
                    );
            double growth = Math.min(1.0D, (age + 1.0D) / 10.0D);
            float alpha = animationAlpha(age, animation.duration);
            double rotation = age * 0.014D;
            VertexConsumer glowConsumer = buffers.getBuffer(
                    RenderType.lightning()
            );

            switch (animation.type) {
                case MODE_WEATHER -> drawModeGlowSurfaces(
                        poseStack,
                        glowConsumer,
                        center,
                        rotation * 5.0D,
                        growth,
                        alpha,
                        ICE_BLUE,
                        CRYSTAL_WHITE,
                        8
                );
                case MODE_SUN_MOON -> drawModeGlowSurfaces(
                        poseStack,
                        glowConsumer,
                        center,
                        rotation * 5.0D,
                        growth,
                        alpha,
                        SUN_GOLD,
                        MOON_BLUE,
                        10
                );
                case MODE_FLAWLESS -> drawModeGlowSurfaces(
                        poseStack,
                        glowConsumer,
                        center,
                        rotation * 5.0D,
                        growth,
                        alpha,
                        PETAL_PINK,
                        ICE_BLUE,
                        12
                );
                case WEATHER_SKILL -> drawWeatherSkillGlowSurfaces(
                        poseStack,
                        glowConsumer,
                        center,
                        rotation * 3.0D,
                        growth,
                        alpha
                );
                case SUN_MOON_SKILL -> drawSunMoonSkillGlowSurfaces(
                        poseStack,
                        glowConsumer,
                        center,
                        rotation * 3.0D,
                        growth,
                        alpha
                );
                case FLAWLESS_BLOOM -> drawFlawlessSkillGlowSurfaces(
                        poseStack,
                        glowConsumer,
                        center,
                        rotation * 3.0D,
                        growth,
                        alpha
                );
                case ULTIMATE -> {
                    double ringRadius = 5.55D * growth;

                    drawDomainGlowSurfaces(
                            poseStack,
                            glowConsumer,
                            center,
                            rotation,
                            growth,
                            alpha
                    );

                    for (int i = 0; i < DOMAIN_SIGNETS.size(); i++) {
                        double angle = rotation
                                + Math.PI * 2.0D * i / DOMAIN_SIGNETS.size();
                        double bob = Math.sin(age * 0.15D + i) * 0.035D;

                        renderSignetItem(
                                minecraft,
                                poseStack,
                                buffers,
                                new ItemStack(DOMAIN_SIGNETS.get(i).get()),
                                center.add(
                                        Math.cos(angle) * ringRadius,
                                        0.24D + bob,
                                        Math.sin(angle) * ringRadius
                                ),
                                angle,
                                1.78D * growth
                                        * Math.min(1.0F, alpha * 1.8F),
                                i
                        );
                    }

                    renderSignetItem(
                            minecraft,
                            poseStack,
                            buffers,
                            new ItemStack(ModItems.SIGNET_OF_EGO.get()),
                            center.add(0.0D, 0.27D, 0.0D),
                            -rotation * 1.75D,
                            3.15D * growth
                                    * Math.min(1.0F, alpha * 1.8F),
                            1314
                    );
                }
                case ULTIMATE_CLOSE -> {
                    if (age < 40.0D) {
                        double morph =
                                Math.min(
                                        1.0D,
                                        age / 40.0D
                                );

                        double ringRadius =
                                4.65D + morph * 0.85D;

                        Vec3 haloCenter =
                                center.add(
                                        0.0D,
                                        5.2D,
                                        0.0D
                                );

                        glowPillar(
                                poseStack,
                                glowConsumer,
                                center.add(
                                        0.0D,
                                        0.15D,
                                        0.0D
                                ),
                                1.15D + morph * 0.65D,
                                11.0D + morph * 4.0D,
                                ULTIMATE_BLACK_PURPLE,
                                Math.min(
                                        1.0F,
                                        alpha * 1.8F
                                ) * 0.24F
                        );

                        for (int i = 0; i < DOMAIN_SIGNETS.size(); i++) {
                            double angle =
                                    rotation * 2.0D +
                                            Math.PI * 2.0D * i /
                                                    DOMAIN_SIGNETS.size();

                            renderVerticalSignetItem(
                                    minecraft,
                                    poseStack,
                                    buffers,
                                    new ItemStack(
                                            DOMAIN_SIGNETS.get(i).get()
                                    ),
                                    haloCenter.add(
                                            Math.cos(angle) * ringRadius,
                                            Math.sin(angle) * ringRadius,
                                            0.0D
                                    ),
                                    1.75D *
                                            Math.min(
                                                    1.0F,
                                                    alpha * 1.8F
                                            ),
                                    2000 + i
                            );
                        }

                        renderVerticalSignetItem(
                                minecraft,
                                poseStack,
                                buffers,
                                new ItemStack(
                                        ModItems.SIGNET_OF_EGO.get()
                                ),
                                haloCenter,
                                4.1D *
                                        Math.min(
                                                1.0F,
                                                alpha * 1.8F
                                        ),
                                520
                        );
                    } else {
                        double reveal =
                                Math.min(
                                        1.0D,
                                        (age - 40.0D) / 8.0D
                                );

                        glowAnnulus(
                                poseStack,
                                glowConsumer,
                                center.add(
                                        0.0D,
                                        0.16D,
                                        0.0D
                                ),
                                5.8D * reveal,
                                7.35D * reveal,
                                128,
                                rotation * 2.0D,
                                ULTIMATE_DEEP_PURPLE,
                                Math.min(
                                        1.0F,
                                        alpha * 1.8F
                                ) * 0.36F
                        );

                        glowPetalFan(
                                poseStack,
                                glowConsumer,
                                center.add(
                                        0.0D,
                                        0.18D,
                                        0.0D
                                ),
                                1.15D * reveal,
                                7.0D * reveal,
                                16,
                                -rotation * 2.4D,
                                ULTIMATE_DEEP_PURPLE,
                                ULTIMATE_BLACK_PURPLE,
                                Math.min(
                                        1.0F,
                                        alpha * 1.8F
                                ) * 0.34F
                        );

                        glowPillar(
                                poseStack,
                                glowConsumer,
                                center.add(
                                        0.0D,
                                        0.16D,
                                        0.0D
                                ),
                                2.8D * reveal,
                                16.5D * reveal,
                                ULTIMATE_BLACK_PURPLE,
                                Math.min(
                                        1.0F,
                                        alpha * 1.8F
                                ) * 0.30F
                        );

                        float statueYaw =
                                resolveStatueYaw(
                                        entity,
                                        partialTick
                                );

                        renderUltimateCloseReference(
                                minecraft,
                                poseStack,
                                buffers,
                                center.add(
                                        0.0D,
                                        0.12D,
                                        0.0D
                                ),
                                14.0D * reveal,
                                Math.min(
                                        1.0F,
                                        alpha * 1.8F
                                ) * 0.92F,
                                statueYaw
                        );
                    }
                }
                default -> {
                }
            }
        }
    }

    private static Vec3 resolveAnimationCenter(
            Animation animation,
            Entity entity,
            float partialTick
    ) {
        if (entity == null) {
            return animation.fallback;
        }

        Vec3 position =
                entity.getPosition(
                        partialTick
                );

        if (
                animation.type !=
                        FlawlessVisualPacket.Type.ULTIMATE_CLOSE
        ) {
            return position;
        }

        float bodyYaw =
                resolveStatueYaw(
                        entity,
                        partialTick
                );

        double yaw =
                Math.toRadians(
                        bodyYaw
                );

        Vec3 forward =
                new Vec3(
                        -Math.sin(yaw),
                        0.0D,
                        Math.cos(yaw)
                );

        return position
                .subtract(
                        forward.scale(
                                3.6D
                        )
                )
                .add(
                        0.0D,
                        0.12D,
                        0.0D
                );
    }

    private static float resolveStatueYaw(
            Entity entity,
            float partialTick
    ) {
        if (
                entity instanceof
                        LivingEntity livingEntity
        ) {
            return Mth.rotLerp(
                    partialTick,
                    livingEntity.yBodyRotO,
                    livingEntity.yBodyRot
            );
        }

        if (entity != null) {
            return entity.getYRot();
        }

        return 0.0F;
    }

    private static void renderVerticalSignetItem(
            Minecraft minecraft,
            PoseStack poseStack,
            MultiBufferSource buffers,
            ItemStack stack,
            Vec3 position,
            double scale,
            int seed
    ) {
        if (
                minecraft.level == null ||
                scale <= 0.001D
        ) {
            return;
        }

        poseStack.pushPose();
        poseStack.translate(
                position.x,
                position.y,
                position.z
        );
        poseStack.mulPose(
                minecraft
                        .getEntityRenderDispatcher()
                        .cameraOrientation()
        );
        poseStack.scale(
                (float) scale,
                (float) scale,
                (float) scale
        );

        minecraft.getItemRenderer().renderStatic(
                stack,
                ItemDisplayContext.FIXED,
                LightTexture.FULL_BRIGHT,
                OverlayTexture.NO_OVERLAY,
                poseStack,
                buffers,
                minecraft.level,
                seed
        );

        poseStack.popPose();
    }

    private static void renderSignetItem(
            Minecraft minecraft,
            PoseStack poseStack,
            MultiBufferSource buffers,
            ItemStack stack,
            Vec3 position,
            double rotation,
            double scale,
            int seed
    ) {
        if (minecraft.level == null || scale <= 0.001D) {
            return;
        }

        poseStack.pushPose();
        poseStack.translate(position.x, position.y, position.z);
        poseStack.mulPose(
                Axis.YP.rotationDegrees((float) Math.toDegrees(-rotation))
        );
        poseStack.mulPose(Axis.XP.rotationDegrees(90.0F));
        poseStack.scale((float) scale, (float) scale, (float) scale);

        minecraft.getItemRenderer().renderStatic(
                stack,
                ItemDisplayContext.FIXED,
                LightTexture.FULL_BRIGHT,
                OverlayTexture.NO_OVERLAY,
                poseStack,
                buffers,
                minecraft.level,
                seed
        );
        poseStack.popPose();
    }

    private static ResourceLocation getUltimateCloseReferenceTexture(
            Minecraft minecraft
    ) {
        if (ultimateCloseReferenceTexture != null) {
            return ultimateCloseReferenceTexture;
        }

        if (ultimateCloseReferenceLoadFailed) {
            return null;
        }

        try {
            StringBuilder encoded =
                    new StringBuilder();

            for (
                    String chunk :
                    ULTIMATE_CLOSE_REFERENCE_DATA
            ) {
                encoded.append(chunk);
            }

            byte[] imageBytes =
                    Base64.getDecoder().decode(
                            encoded.toString()
                    );

            NativeImage image;

            try (
                    ByteArrayInputStream input =
                            new ByteArrayInputStream(
                                    imageBytes
                            )
            ) {
                image = NativeImage.read(input);
            }

            DynamicTexture texture =
                    new DynamicTexture(image);

            minecraft.getTextureManager().register(
                    ULTIMATE_CLOSE_REFERENCE,
                    texture
            );

            ultimateCloseReferenceTexture =
                    ULTIMATE_CLOSE_REFERENCE;

            return ultimateCloseReferenceTexture;
        } catch (Exception exception) {
            ultimateCloseReferenceLoadFailed = true;
            return null;
        }
    }

    private static void renderUltimateCloseReference(
            Minecraft minecraft,
            PoseStack poseStack,
            MultiBufferSource buffers,
            Vec3 position,
            double height,
            float alpha,
            float worldYaw
    ) {
        if (
                minecraft.level == null ||
                        alpha <= 0.001F ||
                        height <= 0.001D
        ) {
            return;
        }

        ResourceLocation texture =
                getUltimateCloseReferenceTexture(
                        minecraft
                );

        if (texture == null) {
            return;
        }

        double width =
                height * 1.14D;

        poseStack.pushPose();

        poseStack.translate(
                position.x,
                position.y,
                position.z
        );

        poseStack.mulPose(
                Axis.YP.rotationDegrees(
                        180.0F - worldYaw
                )
        );

        poseStack.translate(
                0.0D,
                0.0D,
                0.025D
        );

        poseStack.scale(
                (float) width,
                (float) height,
                1.0F
        );

        VertexConsumer consumer =
                buffers.getBuffer(
                        RenderType.entityTranslucent(
                                texture
                        )
                );

        Matrix4f pose =
                poseStack.last().pose();

        Matrix3f normal =
                poseStack.last().normal();

        int color =
                Math.max(
                        0,
                        Math.min(
                                255,
                                (int) (
                                        alpha * 255.0F
                                )
                        )
                );

        consumer.vertex(
                        pose,
                        -0.5F,
                        1.0F,
                        0.0F
                )
                .color(
                        255,
                        255,
                        255,
                        color
                )
                .uv(
                        0.0F,
                        0.0F
                )
                .overlayCoords(
                        OverlayTexture.NO_OVERLAY
                )
                .uv2(
                        LightTexture.FULL_BRIGHT
                )
                .normal(
                        normal,
                        0.0F,
                        0.0F,
                        1.0F
                )
                .endVertex();

        consumer.vertex(
                        pose,
                        0.5F,
                        1.0F,
                        0.0F
                )
                .color(
                        255,
                        255,
                        255,
                        color
                )
                .uv(
                        1.0F,
                        0.0F
                )
                .overlayCoords(
                        OverlayTexture.NO_OVERLAY
                )
                .uv2(
                        LightTexture.FULL_BRIGHT
                )
                .normal(
                        normal,
                        0.0F,
                        0.0F,
                        1.0F
                )
                .endVertex();

        consumer.vertex(
                        pose,
                        0.5F,
                        0.0F,
                        0.0F
                )
                .color(
                        255,
                        255,
                        255,
                        color
                )
                .uv(
                        1.0F,
                        1.0F
                )
                .overlayCoords(
                        OverlayTexture.NO_OVERLAY
                )
                .uv2(
                        LightTexture.FULL_BRIGHT
                )
                .normal(
                        normal,
                        0.0F,
                        0.0F,
                        1.0F
                )
                .endVertex();

        consumer.vertex(
                        pose,
                        -0.5F,
                        0.0F,
                        0.0F
                )
                .color(
                        255,
                        255,
                        255,
                        color
                )
                .uv(
                        0.0F,
                        1.0F
                )
                .overlayCoords(
                        OverlayTexture.NO_OVERLAY
                )
                .uv2(
                        LightTexture.FULL_BRIGHT
                )
                .normal(
                        normal,
                        0.0F,
                        0.0F,
                        1.0F
                )
                .endVertex();

        poseStack.popPose();
    }

