    private static void glowAnnulus(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double innerRadius,
            double outerRadius,
            int segments,
            double phase,
            Color color,
            float alpha
    ) {
        for (int i = 0; i < segments; i++) {
            double angleA = phase + Math.PI * 2.0D * i / segments;
            double angleB = phase + Math.PI * 2.0D * (i + 1) / segments;
            Vec3 innerA = center.add(
                    Math.cos(angleA) * innerRadius,
                    0.0D,
                    Math.sin(angleA) * innerRadius
            );
            Vec3 outerA = center.add(
                    Math.cos(angleA) * outerRadius,
                    0.0D,
                    Math.sin(angleA) * outerRadius
            );
            Vec3 outerB = center.add(
                    Math.cos(angleB) * outerRadius,
                    0.0D,
                    Math.sin(angleB) * outerRadius
            );
            Vec3 innerB = center.add(
                    Math.cos(angleB) * innerRadius,
                    0.0D,
                    Math.sin(angleB) * innerRadius
            );

            glowQuad(
                    poseStack,
                    consumer,
                    innerA,
                    outerA,
                    outerB,
                    innerB,
                    color,
                    alpha * (i % 2 == 0 ? 1.0F : 0.72F)
            );
        }
    }

    private static void glowPetalFan(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double innerRadius,
            double outerRadius,
            int petals,
            double phase,
            Color first,
            Color second,
            float alpha
    ) {
        for (int i = 0; i < petals; i++) {
            double angle = phase + Math.PI * 2.0D * i / petals;
            double halfWidth = 0.105D;
            Vec3 innerA = center.add(
                    Math.cos(angle - halfWidth) * innerRadius,
                    0.0D,
                    Math.sin(angle - halfWidth) * innerRadius
            );
            Vec3 outerA = center.add(
                    Math.cos(angle - halfWidth * 0.48D) * outerRadius,
                    0.025D,
                    Math.sin(angle - halfWidth * 0.48D) * outerRadius
            );
            Vec3 outerB = center.add(
                    Math.cos(angle + halfWidth * 0.48D) * outerRadius,
                    0.025D,
                    Math.sin(angle + halfWidth * 0.48D) * outerRadius
            );
            Vec3 innerB = center.add(
                    Math.cos(angle + halfWidth) * innerRadius,
                    0.0D,
                    Math.sin(angle + halfWidth) * innerRadius
            );

            glowQuad(
                    poseStack,
                    consumer,
                    innerA,
                    outerA,
                    outerB,
                    innerB,
                    i % 2 == 0 ? first : second,
                    alpha
            );
        }
    }

    private static void glowPillar(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 base,
            double halfWidth,
            double height,
            Color color,
            float alpha
    ) {
        Vec3 top = base.add(0.0D, height, 0.0D);

        glowQuad(
                poseStack,
                consumer,
                base.add(-halfWidth, 0.0D, 0.0D),
                base.add(halfWidth, 0.0D, 0.0D),
                top.add(halfWidth * 0.22D, 0.0D, 0.0D),
                top.add(-halfWidth * 0.22D, 0.0D, 0.0D),
                color,
                alpha
        );
        glowQuad(
                poseStack,
                consumer,
                base.add(0.0D, 0.0D, -halfWidth),
                base.add(0.0D, 0.0D, halfWidth),
                top.add(0.0D, 0.0D, halfWidth * 0.22D),
                top.add(0.0D, 0.0D, -halfWidth * 0.22D),
                color,
                alpha
        );
    }

    private static void glowQuad(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 first,
            Vec3 second,
            Vec3 third,
            Vec3 fourth,
            Color color,
            float alpha
    ) {
        Matrix4f pose = poseStack.last().pose();

        consumer.vertex(pose, (float) first.x, (float) first.y, (float) first.z)
                .color(color.red, color.green, color.blue, alpha)
                .endVertex();
        consumer.vertex(pose, (float) second.x, (float) second.y, (float) second.z)
                .color(color.red, color.green, color.blue, alpha)
                .endVertex();
        consumer.vertex(pose, (float) third.x, (float) third.y, (float) third.z)
                .color(color.red, color.green, color.blue, alpha * 0.42F)
                .endVertex();
        consumer.vertex(pose, (float) fourth.x, (float) fourth.y, (float) fourth.z)
                .color(color.red, color.green, color.blue, alpha * 0.42F)
                .endVertex();
    }

