    private static void recordTrailPoint(
            Animation animation,
            Vec3 point,
            long gameTime
    ) {
        if (animation.lastTrailTick == gameTime) {
            return;
        }

        animation.lastTrailTick = gameTime;

        if (
                !animation.trailPoints.isEmpty() &&
                animation.trailPoints
                        .get(animation.trailPoints.size() - 1)
                        .distanceToSqr(point) < 0.0004D
        ) {
            return;
        }

        animation.trailPoints.add(point);
        int maximum = animation.variant == 1 ? 16 : 12;

        while (animation.trailPoints.size() > maximum) {
            animation.trailPoints.remove(0);
        }
    }

    private static void drawArrowTrail(
            PoseStack poseStack,
            VertexConsumer consumer,
            Animation animation,
            Vec3 center,
            double phase,
            float alpha
    ) {
        List<Vec3> points = animation.trailPoints;
        double ribbonRadius = animation.variant == 1 ? 0.24D : 0.16D;

        for (int i = 1; i < points.size(); i++) {
            Vec3 from = points.get(i - 1);
            Vec3 to = points.get(i);
            Vec3 movement = to.subtract(from);

            if (movement.lengthSqr() < 0.000001D) {
                continue;
            }

            Vec3 direction = movement.normalize();
            Vec3 side = new Vec3(-direction.z, 0.0D, direction.x);

            if (side.lengthSqr() < 0.000001D) {
                side = new Vec3(1.0D, 0.0D, 0.0D);
            } else {
                side = side.normalize();
            }

            Vec3 vertical = direction.cross(side).normalize();
            double wave = phase * 5.5D + i * 1.05D;
            Vec3 offsetFrom = side.scale(Math.sin(wave) * ribbonRadius)
                    .add(vertical.scale(Math.cos(wave) * ribbonRadius));
            Vec3 offsetTo = side.scale(
                            Math.sin(wave + 1.05D) * ribbonRadius
                    )
                    .add(vertical.scale(
                            Math.cos(wave + 1.05D) * ribbonRadius
                    ));
            double progress = i / (double) Math.max(1, points.size() - 1);
            float ribbonAlpha = alpha * (float) (
                    0.16D + progress * progress * 0.84D
            );

            line(
                    poseStack,
                    consumer,
                    from.add(offsetFrom),
                    to.add(offsetTo),
                    PETAL_PINK,
                    ribbonAlpha
            );
            line(
                    poseStack,
                    consumer,
                    from.subtract(offsetFrom),
                    to.subtract(offsetTo),
                    ICE_BLUE,
                    ribbonAlpha
            );
            line(
                    poseStack,
                    consumer,
                    from,
                    to,
                    i % 2 == 0 ? CRYSTAL_WHITE : ELYSIA_VIOLET,
                    ribbonAlpha * 0.72F
            );
        }

        double scale = animation.variant == 1 ? 1.35D : 1.0D;

        verticalRingCross(
                poseStack,
                consumer,
                center,
                0.28D * scale,
                32,
                phase * 4.2D,
                PETAL_PINK,
                ICE_BLUE,
                alpha * 0.78F
        );
        heartVerticalCross(
                poseStack,
                consumer,
                center,
                0.20D * scale,
                30,
                -phase * 2.6D,
                CRYSTAL_WHITE,
                DEEP_PINK,
                alpha * 0.82F
        );
        diamondCross(
                poseStack,
                consumer,
                center,
                0.22D * scale,
                phase * 5.0D,
                animation.variant == 1 ? ELYSIA_VIOLET : PETAL_PINK,
                alpha
        );
    }

    private static void drawArrowImpact(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            int variant,
            double age,
            double phase,
            float alpha
    ) {
        double growth = Math.min(1.0D, (age + 1.0D) / 5.0D);
        double scale = (variant == 1 ? 1.45D : 1.0D)
                * growth
                * (1.0D + Math.sin(age * 0.42D) * 0.05D);
        Vec3 bloomCenter = center.add(0.0D, 0.38D * scale, 0.0D);

        magicCircleXZ(
                poseStack,
                consumer,
                center.add(0.0D, 0.03D, 0.0D),
                1.42D * scale,
                phase * 2.3D,
                DEEP_PINK,
                ICE_BLUE,
                alpha * 0.76F
        );
        flowerVerticalCross(
                poseStack,
                consumer,
                bloomCenter,
                1.24D * scale,
                84,
                -phase * 1.7D,
                PETAL_PINK,
                CRYSTAL_WHITE,
                alpha * 0.86F
        );
        heartVerticalCross(
                poseStack,
                consumer,
                bloomCenter,
                0.92D * scale,
                70,
                phase * 0.72D,
                DEEP_PINK,
                ICE_BLUE,
                alpha * 0.82F
        );
        lightWings(
                poseStack,
                consumer,
                bloomCenter,
                0.82D * scale,
                1.02D * scale,
                phase * 1.6D,
                PETAL_PINK,
                ICE_BLUE,
                alpha * 0.58F
        );
        crystalStarburst(
                poseStack,
                consumer,
                bloomCenter,
                1.56D * scale,
                phase * 2.1D,
                DEEP_PINK,
                CRYSTAL_WHITE,
                alpha * 0.78F
        );
        orbitingHearts(
                poseStack,
                consumer,
                bloomCenter,
                1.08D * scale,
                0.21D * scale,
                variant == 1 ? 6 : 4,
                -phase * 2.0D,
                PETAL_PINK,
                ICE_BLUE,
                alpha * 0.72F
        );
    }

    private static void crystalStarburst(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double radius,
            double phase,
            Color first,
            Color second,
            float alpha
    ) {
        int rays = 12;

        for (int i = 0; i < rays; i++) {
            double angle = phase + Math.PI * 2.0D * i / rays;
            double vertical = Math.sin(angle * 2.0D + phase) * radius * 0.34D;
            Vec3 inner = center.add(
                    Math.cos(angle) * radius * 0.22D,
                    vertical * 0.22D,
                    Math.sin(angle) * radius * 0.22D
            );
            Vec3 outer = center.add(
                    Math.cos(angle) * radius,
                    vertical,
                    Math.sin(angle) * radius
            );
            Color color = i % 2 == 0 ? first : second;

            line(
                    poseStack,
                    consumer,
                    inner,
                    outer,
                    color,
                    alpha * (i % 3 == 0 ? 1.0F : 0.68F)
            );
            diamondCross(
                    poseStack,
                    consumer,
                    outer,
                    Math.max(0.05D, radius * 0.055D),
                    -phase * 2.4D + i,
                    color,
                    alpha * 0.82F
            );
        }
    }

    private static void orbitingHearts(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double radius,
            double heartSize,
            int count,
            double phase,
            Color first,
            Color second,
            float alpha
    ) {
        for (int i = 0; i < count; i++) {
            double angle = phase + Math.PI * 2.0D * i / count;
            Vec3 heartCenter = center.add(
                    Math.cos(angle) * radius,
                    Math.sin(angle * 2.0D) * radius * 0.18D,
                    Math.sin(angle) * radius
            );

            heartVerticalCross(
                    poseStack,
                    consumer,
                    heartCenter,
                    heartSize,
                    28,
                    -phase * 0.45D + i * 0.24D,
                    i % 2 == 0 ? first : second,
                    i % 2 == 0 ? CRYSTAL_WHITE : first,
                    alpha
            );
        }
    }

    private static void magicCircleXZ(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double radius,
            double phase,
            Color first,
            Color second,
            float alpha
    ) {
        ringXZ(
                poseStack,
                consumer,
                center,
                radius,
                96,
                phase,
                first,
                second,
                alpha
        );
        ringXZ(
                poseStack,
                consumer,
                center.add(0.0D, 0.025D, 0.0D),
                radius * 0.82D,
                84,
                -phase * 1.35D,
                second,
                first,
                alpha * 0.82F
        );
        ringXZ(
                poseStack,
                consumer,
                center.add(0.0D, 0.050D, 0.0D),
                radius * 0.54D,
                64,
                phase * 1.8D,
                first,
                second,
                alpha * 0.72F
        );

        for (int i = 0; i < 12; i++) {
            double angle = phase + Math.PI * 2.0D * i / 12.0D;
            Vec3 inner = center.add(
                    Math.cos(angle) * radius * 0.58D,
                    0.04D,
                    Math.sin(angle) * radius * 0.58D
            );
            Vec3 outer = center.add(
                    Math.cos(angle) * radius * 0.96D,
                    0.04D,
                    Math.sin(angle) * radius * 0.96D
            );
            line(
                    poseStack,
                    consumer,
                    inner,
                    outer,
                    i % 2 == 0 ? first : second,
                    alpha * 0.68F
            );

            if (i % 2 == 0) {
                diamondCross(
                        poseStack,
                        consumer,
                        outer.add(0.0D, 0.06D, 0.0D),
                        Math.max(0.06D, radius * 0.055D),
                        -phase * 2.0D + i,
                        i % 4 == 0 ? second : first,
                        alpha * 0.78F
                );
            }
        }
    }

    private static void orbitingCrown(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double radius,
            double phase,
            Color first,
            Color second,
            float alpha
    ) {
        ringXZ(
                poseStack,
                consumer,
                center,
                radius,
                72,
                phase,
                first,
                second,
                alpha * 0.76F
        );
        ringXZ(
                poseStack,
                consumer,
                center.add(0.0D, 0.12D, 0.0D),
                radius * 0.72D,
                60,
                -phase * 1.4D,
                second,
                first,
                alpha * 0.62F
        );

        Vec3 previous = null;
        int points = 8;

        for (int i = 0; i <= points; i++) {
            double angle = phase + Math.PI * 2.0D * i / points;
            double wave = i % 2 == 0 ? 0.24D : -0.06D;
            Vec3 current = center.add(
                    Math.cos(angle) * radius,
                    wave,
                    Math.sin(angle) * radius
            );

            if (previous != null) {
                line(
                        poseStack,
                        consumer,
                        previous,
                        current,
                        i % 2 == 0 ? first : second,
                        alpha
                );
            }
            previous = current;

            if (i < points && i % 2 == 0) {
                diamondCross(
                        poseStack,
                        consumer,
                        current,
                        radius * 0.14D,
                        phase * 2.0D + i,
                        i % 4 == 0 ? first : second,
                        alpha * 0.88F
                );
            }
        }
    }

    private static void lightWings(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double width,
            double height,
            double phase,
            Color first,
            Color second,
            float alpha
    ) {
        double flutter = 1.0D + Math.sin(phase * 2.8D) * 0.08D;

        for (int axis = 0; axis < 2; axis++) {
            for (int side = -1; side <= 1; side += 2) {
                Vec3 root = wingPoint(
                        center,
                        axis,
                        side * width * 0.12D,
                        0.0D
                );
                Vec3 top = wingPoint(
                        center,
                        axis,
                        side * width * 0.74D * flutter,
                        height * 0.92D
                );
                Vec3 outer = wingPoint(
                        center,
                        axis,
                        side * width * 1.18D * flutter,
                        height * 0.35D
                );
                Vec3 lower = wingPoint(
                        center,
                        axis,
                        side * width * 0.72D * flutter,
                        -height * 0.34D
                );

                cubicCurve(
                        poseStack,
                        consumer,
                        root,
                        wingPoint(center, axis, side * width * 0.28D, height * 0.58D),
                        wingPoint(center, axis, side * width * 0.52D, height),
                        top,
                        first,
                        alpha
                );
                cubicCurve(
                        poseStack,
                        consumer,
                        top,
                        wingPoint(center, axis, side * width * 1.02D, height * 0.90D),
                        wingPoint(center, axis, side * width * 1.30D, height * 0.55D),
                        outer,
                        second,
                        alpha * 0.92F
                );
                cubicCurve(
                        poseStack,
                        consumer,
                        outer,
                        wingPoint(center, axis, side * width * 1.15D, 0.02D),
                        wingPoint(center, axis, side * width * 0.86D, -height * 0.42D),
                        lower,
                        first,
                        alpha * 0.86F
                );
                cubicCurve(
                        poseStack,
                        consumer,
                        lower,
                        wingPoint(center, axis, side * width * 0.42D, -height * 0.18D),
                        wingPoint(center, axis, side * width * 0.22D, -height * 0.05D),
                        root,
                        second,
                        alpha * 0.80F
                );

                for (int feather = 1; feather <= 4; feather++) {
                    double progress = feather / 5.0D;
                    Vec3 tip = wingPoint(
                            center,
                            axis,
                            side * width * (0.48D + progress * 0.66D) * flutter,
                            height * (0.88D - progress * 1.05D)
                    );
                    cubicCurve(
                            poseStack,
                            consumer,
                            root,
                            wingPoint(
                                    center,
                                    axis,
                                    side * width * (0.22D + progress * 0.22D),
                                    height * (0.34D - progress * 0.08D)
                            ),
                            wingPoint(
                                    center,
                                    axis,
                                    side * width * (0.40D + progress * 0.52D),
                                    height * (0.72D - progress * 0.72D)
                            ),
                            tip,
                            feather % 2 == 0 ? first : second,
                            alpha * 0.54F
                    );
                }
            }
        }
    }

    private static Vec3 wingPoint(
            Vec3 center,
            int axis,
            double horizontal,
            double vertical
    ) {
        return axis == 0
                ? center.add(horizontal, vertical, 0.0D)
                : center.add(0.0D, vertical, horizontal);
    }

    private static void cubicCurve(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 start,
            Vec3 controlA,
            Vec3 controlB,
            Vec3 end,
            Color color,
            float alpha
    ) {
        Vec3 previous = start;
        int segments = 18;

        for (int i = 1; i <= segments; i++) {
            double t = i / (double) segments;
            double inverse = 1.0D - t;
            Vec3 current = new Vec3(
                    inverse * inverse * inverse * start.x
                            + 3.0D * inverse * inverse * t * controlA.x
                            + 3.0D * inverse * t * t * controlB.x
                            + t * t * t * end.x,
                    inverse * inverse * inverse * start.y
                            + 3.0D * inverse * inverse * t * controlA.y
                            + 3.0D * inverse * t * t * controlB.y
                            + t * t * t * end.y,
                    inverse * inverse * inverse * start.z
                            + 3.0D * inverse * inverse * t * controlA.z
                            + 3.0D * inverse * t * t * controlB.z
                            + t * t * t * end.z
            );
            line(
                    poseStack,
                    consumer,
                    previous,
                    current,
                    color,
                    alpha
            );
            previous = current;
        }
    }

    private static void spawnHeldParticles(
            Minecraft minecraft,
            Player player,
            long gameTime
    ) {
        if (
                minecraft.level == null ||
                !player.isUsingItem() ||
                !player.getMainHandItem().is(
                        ModItems.FLAWLESS_BENEDICTION_LEGACY.get()
                ) ||
                gameTime == lastHeldParticleTick ||
                gameTime % 8L != 0L
        ) {
            return;
        }

        lastHeldParticleTick = gameTime;
        double phase = gameTime * 0.18D;

        for (int i = 0; i < 2; i++) {
            double angle = phase + Math.PI * i;
            double x = player.getX() + Math.cos(angle) * 1.28D;
            double y = player.getY() + 0.22D + i * 0.18D;
            double z = player.getZ() + Math.sin(angle) * 1.28D;

            if (i == 1) {
                minecraft.level.addParticle(
                        ParticleTypes.END_ROD,
                        x,
                        y,
                        z,
                        -Math.cos(angle) * 0.012D,
                        0.018D,
                        -Math.sin(angle) * 0.012D
                );
            } else {
                minecraft.level.addParticle(
                        ParticleTypes.CHERRY_LEAVES,
                        x,
                        y,
                        z,
                        0.0D,
                        0.012D,
                        0.0D
                );
            }
        }
    }

    private static void spawnAnimationParticles(
            Minecraft minecraft,
            Animation animation,
            Vec3 center,
            long gameTime,
            double age
    ) {
        if (minecraft.level == null || gameTime == animation.lastParticleTick) {
            return;
        }

        int interval = switch (animation.type) {
            case MODE_WEATHER, MODE_SUN_MOON, MODE_FLAWLESS -> 1;
            case BLOOM_STACK -> 3;
            case WEATHER_SKILL, SUN_MOON_SKILL, FLAWLESS_BLOOM -> 1;
            case ULTIMATE -> 2;
            case ULTIMATE_CLOSE -> 1;
            case ARROW_TRAIL -> 3;
            case ARROW_IMPACT -> 2;
        };

        if (gameTime % interval != 0L) {
            return;
        }

        animation.lastParticleTick = gameTime;

        int count = switch (animation.type) {
            case MODE_WEATHER, MODE_SUN_MOON, MODE_FLAWLESS -> 8;
            case BLOOM_STACK -> 2;
            case WEATHER_SKILL, SUN_MOON_SKILL -> 12;
            case FLAWLESS_BLOOM -> 14;
            case ULTIMATE -> 8;
            case ULTIMATE_CLOSE -> age < 40.0D ? 20 : 48;
            case ARROW_TRAIL -> animation.variant == 1 ? 2 : 1;
            case ARROW_IMPACT -> animation.variant == 1 ? 6 : 4;
        };
        double radius = switch (animation.type) {
            case MODE_WEATHER, MODE_SUN_MOON, MODE_FLAWLESS -> 1.45D;
            case BLOOM_STACK -> 0.55D;
            case WEATHER_SKILL, SUN_MOON_SKILL -> 2.75D;
            case FLAWLESS_BLOOM -> 2.45D;
            case ULTIMATE -> 5.25D;
            case ULTIMATE_CLOSE -> age < 40.0D ? 5.8D : 10.5D;
            case ARROW_TRAIL -> animation.variant == 1 ? 0.42D : 0.28D;
            case ARROW_IMPACT -> animation.variant == 1 ? 2.15D : 1.48D;
        };
        double maxHeight = switch (animation.type) {
            case MODE_WEATHER, MODE_SUN_MOON, MODE_FLAWLESS -> 2.2D;
            case BLOOM_STACK -> 2.8D;
            case WEATHER_SKILL, SUN_MOON_SKILL -> 4.2D;
            case FLAWLESS_BLOOM -> 3.7D;
            case ULTIMATE -> 6.0D;
            case ULTIMATE_CLOSE -> age < 40.0D ? 9.0D : 22.0D;
            case ARROW_TRAIL -> animation.variant == 1 ? 0.55D : 0.36D;
            case ARROW_IMPACT -> animation.variant == 1 ? 3.1D : 2.15D;
        };
        double phase = age * 0.18D;

        for (int i = 0; i < count; i++) {
            double angle = phase + Math.PI * 2.0D * i / count;
            double currentRadius = radius * (
                    0.78D + 0.22D * Math.sin(age * 0.16D + i)
            );
            double x = center.x + Math.cos(angle) * currentRadius;
            double y = center.y + 0.18D
                    + maxHeight * ((i + gameTime) % count) / (double) count;
            double z = center.z + Math.sin(angle) * currentRadius;
            double velocityX = -Math.cos(angle) * 0.010D;
            double velocityZ = -Math.sin(angle) * 0.010D;

            if (
                    animation.type == FlawlessVisualPacket.Type.ARROW_TRAIL ||
                    animation.type == FlawlessVisualPacket.Type.ARROW_IMPACT
            ) {
                minecraft.level.addParticle(
                        i % 4 == 0
                                ? ParticleTypes.FIREWORK
                                : i % 2 == 0
                                ? ParticleTypes.END_ROD
                                : ParticleTypes.CHERRY_LEAVES,
                        x,
                        y,
                        z,
                        velocityX * 1.8D,
                        animation.type == FlawlessVisualPacket.Type.ARROW_TRAIL
                                ? 0.004D
                                : 0.026D,
                        velocityZ * 1.8D
                );
            } else if (
                    animation.type ==
                            FlawlessVisualPacket.Type.ULTIMATE_CLOSE
            ) {
                minecraft.level.addParticle(
                        i % 5 == 0
                                ? ParticleTypes.FIREWORK
                                : i % 3 == 0
                                ? ParticleTypes.END_ROD
                                : ParticleTypes.CHERRY_LEAVES,
                        x,
                        y,
                        z,
                        velocityX * 2.4D,
                        age < 40.0D
                                ? 0.035D
                                : 0.085D,
                        velocityZ * 2.4D
                );
            } else if (
                    animation.type == FlawlessVisualPacket.Type.WEATHER_SKILL ||
                    animation.type == FlawlessVisualPacket.Type.MODE_WEATHER
            ) {
                minecraft.level.addParticle(
                        i % 2 == 0
                                ? ParticleTypes.END_ROD
                                : ParticleTypes.ENCHANTED_HIT,
                        x,
                        y,
                        z,
                        velocityX,
                        0.025D,
                        velocityZ
                );
            } else if (
                    animation.type == FlawlessVisualPacket.Type.SUN_MOON_SKILL ||
                    animation.type == FlawlessVisualPacket.Type.MODE_SUN_MOON
            ) {
                minecraft.level.addParticle(
                        i % 2 == 0
                                ? ParticleTypes.FIREWORK
                                : ParticleTypes.ENCHANTED_HIT,
                        x,
                        y,
                        z,
                        velocityX,
                        0.018D,
                        velocityZ
                );
            } else {
                minecraft.level.addParticle(
                        i % 3 == 0
                                ? ParticleTypes.END_ROD
                                : ParticleTypes.CHERRY_LEAVES,
                        x,
                        y,
                        z,
                        velocityX,
                        0.016D,
                        velocityZ
                );
            }
        }
    }

    private static void ringXZ(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double radius,
            int segments,
            double phase,
            Color first,
            Color second,
            float alpha
    ) {
        Vec3 previous = null;

        for (int i = 0; i <= segments; i++) {
            double angle = phase
                    + Math.PI * 2.0D * i / segments;
            Vec3 current = center.add(
                    Math.cos(angle) * radius,
                    0.0D,
                    Math.sin(angle) * radius
            );

            if (previous != null) {
                line(
                        poseStack,
                        consumer,
                        previous,
                        current,
                        mix(first, second, i / (float) segments),
                        alpha
                );
            }
            previous = current;
        }
    }

    private static void flowerXZ(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double radius,
            int segments,
            double phase,
            Color first,
            Color second,
            float alpha
    ) {
        Vec3 previous = null;

        for (int i = 0; i <= segments; i++) {
            double angle = phase
                    + Math.PI * 2.0D * i / segments;
            double petalRadius = radius * Math.cos(angle * 3.0D);
            Vec3 current = center.add(
                    Math.cos(angle) * petalRadius,
                    Math.sin(angle * 6.0D) * 0.035D,
                    Math.sin(angle) * petalRadius
            );

            if (previous != null) {
                line(
                        poseStack,
                        consumer,
                        previous,
                        current,
                        mix(first, second, i / (float) segments),
                        alpha
                );
            }
            previous = current;
        }
    }

    private static void flowerVerticalCross(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double radius,
            int segments,
            double phase,
            Color first,
            Color second,
            float alpha
    ) {
        Vec3 previousXY = null;
        Vec3 previousZY = null;

        for (int i = 0; i <= segments; i++) {
            double angle = phase
                    + Math.PI * 2.0D * i / segments;
            double petalRadius = radius * Math.cos(angle * 3.0D);
            double horizontal = Math.cos(angle) * petalRadius;
            double vertical = Math.sin(angle) * petalRadius;
            Vec3 currentXY = center.add(horizontal, vertical, 0.0D);
            Vec3 currentZY = center.add(0.0D, vertical, horizontal);
            Color color = mix(first, second, i / (float) segments);

            if (previousXY != null) {
                line(
                        poseStack,
                        consumer,
                        previousXY,
                        currentXY,
                        color,
                        alpha
                );
                line(
                        poseStack,
                        consumer,
                        previousZY,
                        currentZY,
                        color,
                        alpha
                );
            }
            previousXY = currentXY;
            previousZY = currentZY;
        }
    }

    private static void heartVerticalCross(
            PoseStack poseStack,
            VertexConsumer consumer,
            Vec3 center,
            double size,
            int segments,
            double phase,
            Color first,
            Color second,
            float alpha
    ) {
        Vec3 previousXY = null;
        Vec3 previousZY = null;

        for (int i = 0; i <= segments; i++) {
            double angle = Math.PI * 2.0D * i / segments + phase;
            double sin = Math.sin(angle);
            double x = 16.0D * sin * sin * sin * size / 18.0D;
            double y = (
                    13.0D * Math.cos(angle)
                            - 5.0D * Math.cos(angle * 2.0D)
                            - 2.0D * Math.cos(angle * 3.0D)
                            - Math.cos(angle * 4.0D)
            ) * size / 18.0D;
            Vec3 currentXY = center.add(x, y, 0.0D);
            Vec3 currentZY = center.add(0.0D, y, x);
            Color color = mix(first, second, i / (float) segments);

            if (previousXY != null) {
                line(
                        poseStack,
                        consumer,
                        previousXY,
                        currentXY,
                        color,
                        alpha
                );
                line(
                        poseStack,
                        consumer,
                        previousZY,
                        currentZY,
                        color,
                        alpha
                );
            }
            previousXY = currentXY;
            previousZY = currentZY;
        }
    }

